/** Wire contract shared with the mobile executor. Generate its client copy with
 * scripts/sync-planner-contract.cjs; do not maintain two validators. */
export type CreationEnd =
  | { type: 'never' }
  | { type: 'date'; dayLocal: string }
  | { type: 'count'; count: number };
export type CreationAlert =
  | { mode: 'offset'; offsetMinutes: number }
  | { mode: 'custom'; dayLocal: string; timeLocal: string };
export type PlannerCreationV2 = {
  version: 2;
  kind: 'task' | 'event' | 'habit' | 'goal' | 'checklist' | 'note' | 'reminder';
  title: string;
  description?: string;
  color?: string | null;
  icon?: string | null;
  showInToday?: boolean;
  showInCalendar?: boolean;
  startDate?: string;
  endDate?: string;
  time?: string;
  endTime?: string;
  allDay?: boolean;
  frequency?: 'daily' | 'weekly' | 'monthly' | 'yearly';
  weekdays?: number[];
  recurrenceEnd?: CreationEnd;
  alerts?: CreationAlert[];
  location?: string;
  important?: boolean;
  pinned?: boolean;
  audioReferenceIds?: string[];
  items?: string[];
  milestones?: { title: string; dueDate: string }[];
  goalReminder?: {
    enabled: boolean;
    offsetDays: number;
    hour: number;
    minute: number;
    includeMilestones: boolean;
  };
  habit?: {
    mode: 'check' | 'count' | 'value';
    target: number;
    unit?: string;
    customUnitLabel?: string;
    comparator: 'at_least' | 'at_most';
    weeklyMode: 'any_day' | 'specific_days';
    daysOfWeek?: number[];
    windows?: { startTimeLocal: string; endTimeLocal: string }[];
    reminder?: {
      enabled: boolean;
      time: string;
      additionalTimes?: string[];
      daysOfWeek?: number[];
      offsetMinutes?: number;
    };
  };
};

export const HABIT_CREATION_UNITS = [
  'times',
  'min',
  'hours',
  'km',
  'miles',
  'm',
  'foot',
  'kg',
  'pound',
  'liter',
  'gallon',
  'money',
  'calories',
  'steps',
  'pages',
  'glasses',
  'sessions',
  'tasks',
  'items',
  'calls',
  'custom',
] as const;
type Obj = Record<string, unknown>;
const obj = (v: unknown): v is Obj =>
  !!v && typeof v === 'object' && !Array.isArray(v);
const keys = (v: Obj, allowed: string[]) =>
  Object.keys(v).every((k) => allowed.includes(k));
const text = (v: unknown, max: number) =>
  typeof v === 'string' && !!v.trim() && v.length <= max;
const integer = (v: unknown, min: number, max: number) =>
  typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
export function creationDay(v: unknown): v is string {
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const d = new Date(`${v}T12:00:00Z`);
  return Number.isFinite(d.getTime()) && d.toISOString().slice(0, 10) === v;
}
const clock = (v: unknown): v is string =>
  typeof v === 'string' && /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(v);
const days = (v: unknown) =>
  Array.isArray(v) &&
  v.length > 0 &&
  v.length <= 7 &&
  v.every((d) => integer(d, 1, 7)) &&
  new Set(v).size === v.length;
function end(v: unknown, start?: string) {
  if (!obj(v)) return false;
  return v.type === 'never'
    ? keys(v, ['type'])
    : v.type === 'date'
      ? keys(v, ['type', 'dayLocal']) &&
        creationDay(v.dayLocal) &&
        (!start || v.dayLocal >= start)
      : v.type === 'count' &&
        keys(v, ['type', 'count']) &&
        integer(v.count, 1, 10000);
}
function alert(v: unknown) {
  if (!obj(v)) return false;
  return v.mode === 'offset'
    ? keys(v, ['mode', 'offsetMinutes']) && integer(v.offsetMinutes, 0, 525600)
    : v.mode === 'custom' &&
        keys(v, ['mode', 'dayLocal', 'timeLocal']) &&
        creationDay(v.dayLocal) &&
        clock(v.timeLocal);
}
/** null matches the manual form's unrestricted description field. */
export const PLANNER_DESCRIPTION_LIMITS = {
  task: 2000, event: 1000, reminder: 2000, note: 10000,
  goal: null, habit: null, checklist: null,
} as const;
const common = ['version', 'kind', 'title', 'description', 'color', 'icon'];
const visibility = ['showInToday', 'showInCalendar'];
const recurrence = ['frequency', 'weekdays', 'recurrenceEnd'];
const schedule = ['startDate', 'endDate', 'time', 'endTime', 'allDay'];
const fields: Record<PlannerCreationV2['kind'], string[]> = {
  task: [...visibility, ...schedule, ...recurrence, 'alerts'],
  event: [
    ...visibility,
    ...schedule,
    ...recurrence,
    'alerts',
    'location',
    'important',
  ],
  reminder: [...visibility, 'startDate', 'time', ...recurrence],
  habit: [...visibility, 'startDate', 'frequency', 'recurrenceEnd', 'habit'],
  goal: [...visibility, 'startDate', 'endDate', 'milestones', 'goalReminder'],
  checklist: ['items'],
  note: ['pinned', 'audioReferenceIds'],
};
function valid(v: unknown): v is PlannerCreationV2 {
  if (
    !obj(v) ||
    v.version !== 2 ||
    !Object.hasOwn(fields, String(v.kind)) ||
    !text(v.title, 60)
  )
    return false;
  const kind = v.kind as PlannerCreationV2['kind'];
  if (!keys(v, [...common, ...fields[kind]])) return false;
  if (
    v.description !== undefined &&
    (typeof v.description !== 'string' ||
      (PLANNER_DESCRIPTION_LIMITS[kind] != null &&
        v.description.length > PLANNER_DESCRIPTION_LIMITS[kind]!))
  )
    return false;
  if (
    v.color !== undefined &&
    v.color !== null &&
    (typeof v.color !== 'string' || !/^#[\da-fA-F]{6}$/.test(v.color))
  )
    return false;
  if (v.icon !== undefined && v.icon !== null && !text(v.icon, 32))
    return false;
  for (const k of [
    'showInToday',
    'showInCalendar',
    'allDay',
    'important',
    'pinned',
  ])
    if (v[k] !== undefined && typeof v[k] !== 'boolean') return false;
  for (const k of ['startDate', 'endDate'])
    if (v[k] !== undefined && !creationDay(v[k])) return false;
  for (const k of ['time', 'endTime'])
    if (v[k] !== undefined && !clock(v[k])) return false;
  const start = v.startDate as string | undefined;
  if (v.endDate && (!start || (v.endDate as string) < start)) return false;
  if ((v.time || v.endTime) && (!start || v.allDay === true)) return false;
  if (v.endTime && !v.time) return false;
  if (v.allDay === false && !v.time) return false;
  // A timed event with an end date needs an explicit end clock. Do not invent
  // midnight (which can precede its start) or an unrequested duration.
  if (kind === 'event' && v.time && v.endDate && !v.endTime) return false;
  if (
    v.endTime &&
    (!v.endDate || v.endDate === start) &&
    (v.endTime as string) < (v.time as string)
  )
    return false;
  if (
    v.frequency !== undefined &&
    (typeof v.frequency !== 'string' ||
      !['daily', 'weekly', 'monthly', 'yearly'].includes(v.frequency))
  )
    return false;
  if (v.frequency && !start) return false;
  if (
    v.weekdays !== undefined &&
    (v.frequency !== 'daily' || !days(v.weekdays))
  )
    return false;
  if (
    v.recurrenceEnd !== undefined &&
    (!v.frequency || !end(v.recurrenceEnd, start))
  )
    return false;
  if (
    v.alerts !== undefined &&
    (!Array.isArray(v.alerts) ||
      !start ||
      !v.alerts.every(alert) ||
      (kind === 'task' && v.alerts.length > 1))
  )
    return false;
  if (
    Array.isArray(v.alerts) &&
    v.alerts.some((a) => obj(a) && a.mode === 'offset' && !v.time)
  )
    return false;
  if (kind === 'event' && !start) return false;
  if (v.location !== undefined && !text(v.location, 2000)) return false;
  if (kind === 'reminder' && (!start || !v.time)) return false;
  if (kind === 'goal') {
    if (!start || !v.endDate) return false;
    if (
      v.milestones !== undefined &&
      (!Array.isArray(v.milestones) ||
        !v.milestones.every(
          (s, index, stages) =>
            obj(s) &&
            keys(s, ['title', 'dueDate']) &&
            text(s.title, 120) &&
            creationDay(s.dueDate) &&
            s.dueDate >= start &&
            s.dueDate <= String(v.endDate) &&
            (index === 0 ||
              s.dueDate >= (stages[index - 1] as { dueDate: string }).dueDate),
        ))
    )
      return false;
    if (v.goalReminder !== undefined) {
      const r = v.goalReminder;
      if (
        !obj(r) ||
        !keys(r, [
          'enabled',
          'offsetDays',
          'hour',
          'minute',
          'includeMilestones',
        ]) ||
        typeof r.enabled !== 'boolean' ||
        ![0, 1, 2, 7].includes(Number(r.offsetDays)) ||
        !integer(r.offsetDays, 0, 7) ||
        !integer(r.hour, 0, 23) ||
        !integer(r.minute, 0, 59) ||
        typeof r.includeMilestones !== 'boolean'
      )
        return false;
    }
  }
  if (
    kind === 'checklist' &&
    (!Array.isArray(v.items) ||
      !v.items.length ||
      !v.items.every((i) => text(i, 120)))
  )
    return false;
  if (kind === 'note') {
    if (
      !text(v.description, 10000) &&
      !(Array.isArray(v.audioReferenceIds) && v.audioReferenceIds.length)
    )
      return false;
    if (
      v.audioReferenceIds !== undefined &&
      (!Array.isArray(v.audioReferenceIds) ||
        !v.audioReferenceIds.every((id) => text(id, 120)) ||
        new Set(v.audioReferenceIds).size !== v.audioReferenceIds.length)
    )
      return false;
  }
  if (kind === 'habit') {
    const h = v.habit;
    if (
      !start ||
      !['daily', 'weekly'].includes(String(v.frequency)) ||
      !obj(h) ||
      !keys(h, [
        'mode',
        'target',
        'unit',
        'customUnitLabel',
        'comparator',
        'weeklyMode',
        'daysOfWeek',
        'windows',
        'reminder',
      ])
    )
      return false;
    if (
      !['check', 'count', 'value'].includes(String(h.mode)) ||
      !['at_least', 'at_most'].includes(String(h.comparator)) ||
      !['any_day', 'specific_days'].includes(String(h.weeklyMode))
    )
      return false;
    if (
      typeof h.target !== 'number' ||
      !Number.isFinite(h.target) ||
      h.target < 0 ||
      (h.target === 0 && h.comparator !== 'at_most') ||
      (h.mode !== 'value' && !Number.isInteger(h.target))
    )
      return false;
    if (h.mode === 'check' && (h.target !== 1 || h.comparator !== 'at_least'))
      return false;
    if (h.mode === 'check' && h.unit !== undefined && h.unit !== 'times')
      return false;
    if (
      h.mode === 'count' &&
      h.unit !== undefined &&
      ![
        'times',
        'steps',
        'pages',
        'glasses',
        'sessions',
        'tasks',
        'items',
        'calls',
        'custom',
      ].some((unit) => unit === h.unit)
    )
      return false;
    if (
      h.unit !== undefined &&
      !(HABIT_CREATION_UNITS as readonly unknown[]).includes(h.unit)
    )
      return false;
    if (h.unit === 'custom' && !text(h.customUnitLabel, 30)) return false;
    if (
      h.customUnitLabel !== undefined &&
      (h.unit !== 'custom' || !text(h.customUnitLabel, 30))
    )
      return false;
    if (h.mode === 'value' && !h.unit) return false;
    if (h.daysOfWeek !== undefined && !days(h.daysOfWeek)) return false;
    if (
      v.frequency === 'weekly' &&
      h.weeklyMode === 'specific_days' &&
      !h.daysOfWeek
    )
      return false;
    if (
      v.frequency === 'weekly' &&
      h.weeklyMode === 'any_day' &&
      (h.daysOfWeek || h.windows)
    )
      return false;
    if (h.windows !== undefined) {
      if (!Array.isArray(h.windows) || !h.windows.length) return false;
      let last = '';
      for (const w of h.windows) {
        if (
          !obj(w) ||
          !keys(w, ['startTimeLocal', 'endTimeLocal']) ||
          !clock(w.startTimeLocal) ||
          !clock(w.endTimeLocal) ||
          w.endTimeLocal <= w.startTimeLocal ||
          w.startTimeLocal < last
        )
          return false;
        last = w.endTimeLocal;
      }
    }
    if (h.reminder !== undefined) {
      const r = h.reminder;
      if (
        !obj(r) ||
        !keys(r, [
          'enabled',
          'time',
          'additionalTimes',
          'daysOfWeek',
          'offsetMinutes',
        ]) ||
        typeof r.enabled !== 'boolean' ||
        !clock(r.time)
      )
        return false;
      if (
        r.daysOfWeek !== undefined &&
        (v.frequency !== 'weekly' || !days(r.daysOfWeek))
      )
        return false;
      if (
        r.offsetMinutes !== undefined &&
        (!h.windows || !integer(r.offsetMinutes, 1, 10080))
      )
        return false;
      if (
        r.additionalTimes !== undefined &&
        (h.windows ||
          !Array.isArray(r.additionalTimes) ||
          !r.additionalTimes.every(clock) ||
          new Set([r.time, ...r.additionalTimes]).size !==
            r.additionalTimes.length + 1)
      )
        return false;
    }
  }
  return true;
}

/** Atomic validation: no filtering/truncation that could turn a partial plan into success. */
export function normalizePlannerCreationsV2(
  value: unknown,
): PlannerCreationV2[] {
  if (!Array.isArray(value) || value.length > 6 || !value.every(valid))
    return [];
  return JSON.parse(JSON.stringify(value)) as PlannerCreationV2[];
}
